local _CE_KEYS="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local _CE_LOOKUP={}
for i=1,#_CE_KEYS do _CE_LOOKUP[_CE_KEYS:sub(i,i)]=i-1 end
local _CE_LOADED={}
local function _CE_SOURCE(name)
    if _CE_LOADED[name] then return _CE_LOADED[name] end
    local rec=_CE_DATA[name]
    if not rec then return nil end
    if rec[1]==0 then
        _CE_LOADED[name]=rec[2]
        return rec[2]
    end
    local encoded=table.concat(rec[2])
    local state=rec[1]
    local acc,bits=0,0
    local pieces,buffer={},{}
    for i=1,#encoded do
        local digit=_CE_LOOKUP[encoded:sub(i,i)]
        if digit then
            acc=acc*64+digit
            bits=bits+6
            if bits>=8 then
                bits=bits-8
                local divisor=2^bits
                local value=math.floor(acc/divisor)%256
                acc=acc%divisor
                state=(state*73+41)%256
                buffer[#buffer+1]=string.char(bit32.bxor(value,state))
                if #buffer>=4096 then
                    pieces[#pieces+1]=table.concat(buffer)
                    table.clear(buffer)
                end
            end
        end
    end
    if #buffer>0 then pieces[#pieces+1]=table.concat(buffer) end
    local text=table.concat(pieces)
    _CE_LOADED[name]=text
    return text
end
local _CE_ENV=(getgenv and getgenv()) or _G
local function _CE_GET(url,cached)
    if type(url)=="string" then
        local subpath=url:match("^https://raw%.githubusercontent%.com/DanoninCat/DanoninScript/[^/]+/(.+)$")
        if subpath then
            local data=_CE_SOURCE(subpath)
            if not data then
                error("[CAT EMPIRE] Recurso ausente no loader: "..subpath,0)
            end
            return data
        end
    end
    return game:HttpGet(url,cached)
end
_CE_ENV.__CE_BUNDLE_GET=_CE_GET
local function _CE_RUN(path,...)
    local src=_CE_SOURCE(path)
    if not src then error("[CAT EMPIRE] Rota nÃ£o incorporada: "..path,0) end
    local fn,reason=loadstring(src)
    if not fn then error("[CAT EMPIRE] Erro no mÃ³dulo "..path..": "..tostring(reason),0) end
    return fn(...)
end
local function _CE_TITLE()
    local ok,info=pcall(function()
        return game:GetService("MarketplaceService"):GetProductInfo(game.PlaceId)
    end)
    if ok and type(info)=="table" and type(info.Name)=="string" and #info.Name>0 then
        return info.Name
    end
    return game.Name
end
_CE_ENV.__CE_GAME_NAME=_CE_TITLE()
_CE_ENV.__CE_GAME_ICON="rbxthumb://type=GameIcon&id="..tostring(game.GameId).."&w=512&h=512"
local function _CE_FINGERPRINT()
    local s=game:GetService("ReplicatedStorage")
    local remotes=s:FindFirstChild("Remotes") or s:WaitForChild("Remotes",5)
    if not remotes then return false end
    for _,v in ipairs({"InventoryRequest","InventoryResult","TraitRerollRequest","TraitRerollResult","HalloweenShop"}) do
        if not remotes:FindFirstChild(v) then return false end
    end
    for _,v in ipairs({"TraitData","UnitData","ItemData","HalloweenData"}) do
        if not s:FindFirstChild(v) then return false end
    end
    return true
end
local function _CE_START()
    local place,universe=game.PlaceId,game.GameId
    local route
    if place==9818210203 or place==9818227981 then
        route="Valoblox/Main.lua"
    elseif place==84448037861644 then
        route="CAT_EMPIRE_FPS844/Main.lua"
    elseif place==93466613073564 then
        route="ScopedV2/Patch.lua"
    elseif place==106198175232796 then
        route="Game106/Main.lua"
    elseif place==84554009750048 then
        route="SummonAMonster/Main.lua"
    elseif place==104856666707760 or place==108448382032231 or universe==104856666707760 then
        route="FPS104/Main.lua"
    elseif place==124216119978534 or universe==124216119978534 then
        route="SettingUpAPet/Main.lua"
    elseif place==99881468171809 then
        route="StealABrainrot/Main.lua"
    elseif place==114326934417838 or universe==114326934417838 then
        route="BreakAndStealAnEgg/Main.lua"
    elseif place==105596644794991 or universe==105596644794991 or _CE_FINGERPRINT() then
        route="UntitledDefense105/Main.lua"
    end
    if not route then
        return _CE_RUN("Loader/Legacy.lua")
